fn rolling_max(numbers: Vec<i32>) -> Vec<i32> {
    let mut result = Vec::with_capacity(numbers.len());
    let mut current_max = i32::MIN;

    for &num in &numbers {
        if num > current_max {
            current_max = num;
        }
        result.push(current_max);
    }

    result
}

